@Readiness
@ApplicationScoped
class LedgerReachable(private val ds: DataSource) : HealthCheck {
    override fun call(): HealthCheckResponse =
        try {
            ds.connection.use { c ->                       // waits for a pooled connection
                if (c.isValid(1)) HealthCheckResponse.up("ledger") else HealthCheckResponse.down("ledger")
            }
        } catch (e: SQLException) {
            HealthCheckResponse.down("ledger")
        }
}

